select case when suppliers.rating >= 4.1 then 'high' when suppliers.rating >= 2.3 then 'mid' else 'low' end as rating_bucket, suppliers.country, round(avg(inventory.quantity), 2) as avg_quantity from inventory join products on inventory.product_id = products.id join suppliers on products.supplier_id = suppliers.id group by case when suppliers.rating >= 4.1 then 'high' when suppliers.rating >= 2.3 then 'mid' else 'low' end, suppliers.country having round(avg(inventory.quantity), 2) > 58 order by avg_quantity desc;
